from lib import *
r=[]
r.append(R(6900701,"चिकन, पास्ता और पालक सूप","दोपहर या रात के खाने में इस स्वादिष्ट सूप से गरमाहट पाएँ। इसमें साबुत अनाज, कम वसा वाला प्रोटीन और कुछ सब्ज़ियाँ भी शामिल हैं।","4","1 1/4 कप सूप + 2 छोटे चम्मच चीज़",
["14 औंस, 1 डिब्बा कम सोडियम वाला चिकन ब्रॉथ","14.5 औंस, 1 डिब्बा डिब्बाबंद कटे हुए टमाटर","2 औंस साबुत अनाज या मल्टीग्रेन पास्ता (जैसे रोटिनी)","2 कप कटा हुआ पका चिकन ब्रेस्ट","1 कप दबाकर भरी हुई बेबी पालक","1/4 कप कटी हुई ताज़ी तुलसी","1 बड़ा चम्मच एक्स्ट्रा वर्जिन जैतून का तेल","1/4 छोटा चम्मच नमक","2 बड़े चम्मच कसा हुआ पारमेसन चीज़"],
["एक मध्यम सॉसपैन में ब्रॉथ और टमाटर को उनके तरल के साथ मिलाएँ और तेज़ आँच पर उबालें। पास्ता डालकर चलाएँ, फिर उबाल आने दें, आँच धीमी करें, ढक दें और 6 मिनट तक या पास्ता के बस नरम होने तक धीमी आँच पर पकाएँ।","आँच से हटाएँ और चीज़ को छोड़कर बाकी सामग्री मिलाएँ। स्वाद रच-बस जाने और गरम होने के लिए ढककर 5 मिनट रहने दें। ऊपर से चीज़ डालकर परोसें।"]))
r.append(R(6901477,"कैलिफ़ोर्निया खजूर और मेवे के बार","ये बार चलते-फिरते नाश्ते या स्नैक के लिए एकदम सही हैं। कैलिफ़ोर्निया खजूर, ओट्स और चिया बीज जैसी पोषक तत्वों से भरपूर सामग्री से लबालब, ये सबको पसंद आएँगे। और इससे भी अच्छी बात यह है कि बार को अलग-अलग लपेटकर, एयरटाइट डिब्बे में रखकर फ्रीज़र में छह महीने तक रखा जा सकता है। बस हर बार निकालें और खाने से पहले कमरे के तापमान पर पिघलने दें।","16","1 बार",
["1 कप कैलिफ़ोर्निया खजूर (गुठली निकले और कटे हुए)","1 1/4 कप जल्दी पकने वाले रोल्ड ओट्स","3 बड़े चम्मच साबुत गेहूँ का आटा (या ग्लूटेन-फ्री पसंद हो तो कुट्टू का आटा)","2 बड़े चम्मच गेहूँ के भ्रूण (व्हीट जर्म)","2 बड़े चम्मच पिसे हुए अलसी के बीज","1 बड़ा चम्मच चिया बीज","1/2 कप पेकान (कटे हुए)","1 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच पिसी दालचीनी","1/4 कप पीनट बटर (क्रीमी)","1/4 कप बिना स्वाद वाला तेल (जैसे वनस्पति या एवोकाडो तेल)","1/4 कप मेपल सिरप","1 छोटा चम्मच संतरे का छिलका (कसा हुआ)","1/4 छोटा चम्मच वनीला एक्सट्रैक्ट"],
["ओवन को 350°F पर पहले से गरम करें और 8x8 इंच के चौकोर पैन में चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","एक कटोरे में खजूर, ओट्स, आटा, व्हीट जर्म, अलसी, चिया, पेकान, नमक और दालचीनी डालकर अच्छी तरह मिलाएँ। खजूर को तोड़कर पूरे मिश्रण में मिलाना न भूलें।","एक छोटे सॉसपैन में धीमी आँच पर पीनट बटर, तेल और मेपल सिरप डालें। अच्छी तरह मिलने तक फेंटें और आँच से हटा लें। कसा हुआ छिलका और वनीला मिलाएँ।","गीली सामग्री को सूखी सामग्री में डालें और सब कुछ समान रूप से लिपटने तक चलाएँ। खजूर को तोड़ते रहें और पूरे मिश्रण में मिलाएँ।","मिश्रण को पैन में समान रूप से फैलाएँ और किनारों व कोनों में अच्छी तरह दबाना न भूलें।","किनारों के सुनहरे होने तक 30 मिनट बेक करें।","पैन को कूलिंग रैक पर रखें और मिश्रण को निकालने और काटने से पहले पूरी तरह ठंडा होने दें। जल्दी ठंडा करने के लिए पैन को फ्रिज में रखा जा सकता है।","चर्मपत्र कागज़ (पार्चमेंट पेपर) की मदद से बार को पैन से निकालें। कटिंग बोर्ड पर रखें और 16 बार में काट लें।"]))
r.append(R(6904987,"मिली-जुली सब्ज़ियों वाला मसाला ऑमलेट","यह रेसिपी मे अब्राहम फ्राइडेल की इंडियन क्विज़ीन डायबिटीज़ कुकबुक से है।","2","1/2 ऑमलेट",
["2 छोटे चम्मच सूरजमुखी का तेल","1 मध्यम लाल प्याज़ (बारीक कटा हुआ)","1 साबुत ताज़ी हरी मिर्च (बारीक कटी हुई)","1 फाँक लहसुन (बारीक कटा हुआ)","1/4 छोटा चम्मच हल्दी (पिसी हुई)","1 छोटा चम्मच पिसा जीरा","1 मध्यम टमाटर (बारीक कटा हुआ)","2 बड़े अंडे (फेंटे हुए)","1/4 छोटा चम्मच नमक","1 बड़ा चम्मच ताज़ा हरा धनिया (कटा हुआ)"],
["एक कास्ट आयरन फ्राइंग पैन में मध्यम-तेज़ आँच पर तेल गरम करें। लाल प्याज़, हरी मिर्च, लहसुन और हल्दी डालें और नरम होने तक भूनें।","आँच मध्यम करें और जीरा व टमाटर डालें। बीच-बीच में चलाते हुए 2 मिनट भूनें।","फेंटे हुए अंडे डालें और पैन को घुमाएँ ताकि अंडे नीचे से जम जाएँ। लगभग 2-3 मिनट पकाएँ।","जब अंडे पूरी तरह पक जाएँ, तो ऑमलेट को मोड़ें और ऊपर से नमक और ताज़ा हरा धनिया छिड़कें। गरमागरम परोसें।"]))
r.append(R(6905037,"बेक्ड बारबेक्यू चिकन टेंडर्स","चिकन टेंडर्स को बेक करना सेहतमंद विकल्प है जो फिर भी स्वाद से भरपूर है। यह बारबेक्यू संस्करण ताज़ा खट्टापन जोड़ता है जिसका आनंद पूरा परिवार लेगा।","4","3 चिकन टेंडर्स",
["1 कप टमाटर सॉस (बिना नमक मिलाए)","2 बड़े चम्मच सेब का सिरका","1 बड़ा चम्मच डिजॉन सरसों","1 बड़ा चम्मच शहद","1 छोटा चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच लहसुन पाउडर","1/2 छोटा चम्मच प्याज़ पाउडर","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","1 1/2 पाउंड चिकन टेंडरलॉइन (बिना ब्रेडिंग के)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","एक कटोरे में टमाटर सॉस, सेब का सिरका, डिजॉन सरसों, शहद, स्मोक्ड पेपरिका, लहसुन पाउडर, प्याज़ पाउडर, कोशर नमक और काली मिर्च को फेंटकर मिलाएँ।","बारबेक्यू सॉस का आधा हिस्सा बाद में इस्तेमाल के लिए अलग रख दें।","चिकन टेंडर्स को दोबारा बंद होने वाले प्लास्टिक बैग या उथली डिश में रखें।","बारबेक्यू सॉस के मिश्रण का बाकी आधा हिस्सा चिकन टेंडर्स पर डालें। बैग को बंद करें या डिश को ढक दें और चिकन को फ्रिज में कम से कम 30 मिनट मैरिनेट होने दें।","चिकन टेंडर्स को तैयार बेकिंग शीट पर सजाकर रखें।","पहले से गरम ओवन में लगभग 20 मिनट या चिकन के पूरी तरह पकने तक बेक करें, बीच में एक बार पलटें।","बची हुई बारबेक्यू सॉस के साथ परोसें।"]))
r.append(R(6905433,"स्वीट चिली चिकन, शकरकंद और ब्रोकली","यह मधुमेह के अनुकूल भोजन हफ़्ते के दिनों का आसान रात का खाना है जिसका आनंद पूरा परिवार ले सकता है। कम वसा वाले प्रोटीन, स्टार्च वाली और बिना स्टार्च वाली सब्ज़ियों को मिलाकर, यह भोजन उन लोगों के लिए बढ़िया विकल्प है जो सेहतमंद खाना चाहते हैं और अपने मधुमेह को नियंत्रित करना चाहते हैं।","4","1 चिकन फ़िलेट, 1/2 कप आलू और 1/4 कप ब्रोकली",
["2 मध्यम शकरकंद (छिले और मध्यम टुकड़ों में कटे हुए)","2 बड़े चम्मच + 1 छोटा चम्मच जैतून का तेल (बाँटकर)","1/4 छोटा चम्मच नमक","2 ब्रेस्ट, लगभग 8 औंस बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (4 पतले फ़िलेट में कटे हुए)","1 गुच्छा ब्रोकली (फूलों में बँटी हुई (लगभग 1 पाउंड))","2 बड़े चम्मच स्वीट चिली सॉस"],
["ओवन को 425 डिग्री F पर पहले से गरम करें। एक बड़ी बेकिंग शीट पर चर्मपत्र कागज़ (पार्चमेंट पेपर) बिछाएँ।","शकरकंद को 1 बड़े चम्मच जैतून के तेल और नमक के साथ मिलाएँ। बेकिंग शीट पर एक परत में फैलाएँ। ओवन में रखें और 10 मिनट बेक करें।","इस बीच, एक बड़ी कड़ाही को मध्यम-तेज़ आँच पर पहले से गरम करें।","कड़ाही गरम होने पर 1 बड़ा चम्मच तेल और चिकन डालें। दोनों तरफ़ सुनहरा भूरा होने तक सेकें (लेकिन पूरी तरह न पकाएँ)। आँच से हटा लें।","शकरकंद को 10 मिनट बेक होने के बाद, बेकिंग शीट निकालें और उसमें चिकन और ब्रोकली डालें। ब्रोकली पर बचा हुआ 1 छोटा चम्मच जैतून का तेल डालें।","बेकिंग शीट को ओवन में रखें और चिकन के पूरी तरह पकने और सब्ज़ियों के नरम होने तक पकाते रहें।","ओवन से निकालें और प्लेटों में बाँट दें। ऊपर से स्वीट चिली सॉस डालें और परोसें।"]))
r.append(R(6906210,"बैंगन लज़ान्या रूलाड","ये रूलाड हफ़्ते के दिनों के लिए एक सुरुचिपूर्ण, फिर भी आसान और पौष्टिक रात का खाना बनते हैं। बैंगन के टुकड़े लज़ान्या नूडल्स से जल्दी पकते हैं और बिना स्टार्च वाली वे सब्ज़ियाँ जोड़ते हैं जो कैसरोल और नूडल्स वाले व्यंजनों में अक्सर नहीं होतीं।","6","2 रूलाड",
["3 स्प्रे, 0.75 ग्राम नॉनस्टिक एक्स्ट्रा वर्जिन जैतून तेल कुकिंग स्प्रे (बाँटकर इस्तेमाल करें)","2 मध्यम बैंगन (छिले हुए और 12, 1/2 इंच मोटे टुकड़ों में कटे हुए)","2 कप 1% वसा वाला, बिना नमक मिलाए कॉटेज चीज़","1/2 कप पार्ट-स्किम मोज़ेरेला (कसा हुआ)","2 बड़े अंडे की सफ़ेदी","1/2 छोटा चम्मच प्याज़ पाउडर","1/4 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच सूखी तुलसी","1/2 छोटा चम्मच सूखा अजवायन","1 छोटा चम्मच सूखा अजमोदा","1, 24.5 औंस का जार कम सोडियम वाली मरीनारा सॉस","2 बड़े चम्मच पारमेसन चीज़ (कसा हुआ)"],
["ओवन को 450°F पर पहले से गरम करें। 9x13 इंच की बेकिंग डिश पर हल्का सा कुकिंग स्प्रे करें।","हर बैंगन को 6, 1/2 इंच मोटे टुकड़ों में काटें। बेकिंग शीट के ऊपर रखे रैक पर रखें और हल्का सा कुकिंग स्प्रे करें। बैंगन को ओवन में 15 मिनट, नरम होने तक रोस्ट करें।","इस बीच, एक मध्यम कटोरे में कॉटेज चीज़, मोज़ेरेला चीज़, अंडे की सफ़ेदी और मसाले मिलाएँ।","बैंगन को ओवन से निकालें और थोड़ा ठंडा होने दें। ओवन का तापमान घटाकर 375°F कर दें।","बेकिंग डिश में 1 कप मरीनारा सॉस डालें और तली को ढकने के लिए फैलाएँ।","बैंगन के एक टुकड़े के एक सिरे पर कॉटेज चीज़ के मिश्रण का 2 बड़े चम्मच रखें। रूलाड बनाने के लिए धीरे से लपेटें। इसे जोड़ वाली तरफ़ नीचे करके बेकिंग डिश में रखें। बाकी 11 बैंगन के टुकड़ों के साथ यही दोहराएँ।","बची हुई मरीनारा सॉस रूलाड के ऊपर डालें और ऊपर से पारमेसन चीज़ छिड़कें। बिना ढके 30 मिनट बेक करें।"]))
r.append(R(6908410,"हरी मटर का ह्यूमस","हरी मटर का ह्यूमस पारंपरिक ह्यूमस का जीवंत और ताज़गी भरा रूप है, जिसमें मटर की मिठास और चटक हरा रंग शामिल है। यह वसंत और गर्मियों की सभाओं के लिए, या जब भी आप पारंपरिक ह्यूमस का अनोखा और स्वादिष्ट रूप चाहें, बढ़िया विकल्प है।","4","1/2 कप",
["1 1/2 कप फ्रोज़न मटर (पिघलाई हुई)","1/2 कप डिब्बाबंद छोले (बिना नमक मिलाए, पानी निथारे और धोए हुए)","1/4 कप ताज़ा पुदीना","2 बड़े चम्मच ताहिनी","1 बड़ा चम्मच नीबू का रस","1 फाँक लहसुन (बारीक कटा हुआ)","2 बड़े चम्मच जैतून का तेल","1/2 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच पानी (ज़रूरत के अनुसार)"],
["फ़ूड प्रोसेसर में पिघलाई हुई हरी मटर, छोले, ताज़ा पुदीना, ताहिनी, ताज़ा नीबू का रस, बारीक कटा लहसुन, जैतून का तेल, पिसा जीरा, नमक और काली मिर्च डालें। सामग्री के टूटना शुरू होने तक मिश्रण को पल्स करें।","फ़ूड प्रोसेसर चलते हुए, धीरे-धीरे पानी डालें, जब तक कि मिश्रण चिकना और मलाईदार न हो जाए। आपको प्रोसेसर को एक-दो बार रोककर किनारों से मिश्रण खुरचना पड़ सकता है। चखें और ज़रूरत हो तो मसाले ठीक करें।"]))
r.append(R(6909702,"रोस्टेड फूलगोभी, प्याज़ और शकरकंद","सब्ज़ियों को रोस्ट करने से उनकी प्राकृतिक मिठास उभर आती है। गरम जायफल और चुटकी भर नमक के साथ, यह पोर्क टेंडरलॉइन या रोस्टेड चिकन के लिए एकदम सही साइड डिश है।","4","3/4 कप",
["3 कप फूलगोभी के फूल (1 इंच के टुकड़ों में कटे हुए)","6 औंस शकरकंद (छिले और 3/4 इंच के टुकड़ों में कटे हुए)","1 मध्यम प्याज़ (8 फाँकों में कटा हुआ)","1 बड़ा चम्मच कनोला तेल","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच पिसा जायफल"],
["ओवन को 425°F पर पहले से गरम करें।","फूलगोभी, शकरकंद और प्याज़ को फ़ॉइल बिछी बड़ी बेकिंग शीट पर रखें। ऊपर से तेल डालें और अच्छी तरह लिपटने तक धीरे से मिलाएँ। सब्ज़ियों को एक परत में सजाएँ और 10 मिनट बेक करें। चलाएँ और 10–11 मिनट या शकरकंद के नरम होने तक बेक करें। ओवन से निकालें।","ऊपर से समान रूप से नमक और जायफल छिड़कें। सब्ज़ियों को फ़ॉइल में लपेटें और किनारे बंद कर दें। स्वाद रच-बस जाने और प्राकृतिक रस के थोड़ा निकलने के लिए 10 मिनट रहने दें।"]))
r.append(R(6910724,"तरबूज़ क्विनोआ सलाद","यह तरबूज़ क्विनोआ सलाद पौष्टिक सब्ज़ियों और पेट भरने वाले क्विनोआ से भरपूर है जो आपको घंटों तक भरा रखेगा। गर्मियों में जब तरबूज़ अपने चरम पर हो, तब स्वाद के धमाके के लिए इसे बनाकर देखें।","4","2 कप सलाद (प्रति सर्विंग 1/2 कप क्विनोआ)",
["1 कप कम सोडियम वाला वेजिटेबल ब्रॉथ","1/2 कप क्विनोआ (धोया हुआ)","5 औंस बेबी अरुगुला","2 कप तरबूज़ (मध्यम टुकड़ों में कटा हुआ)","1 एवोकाडो (मध्यम टुकड़ों में कटा हुआ)","1/4 कप नमकीन कद्दू के बीज","1/2 औंस ताज़ा पुदीना (पत्तियाँ हाथ से फाड़ी हुई)","4 औंस वसा रहित फ़ेटा चीज़","1 मध्यम नीबू (छिलका कसा हुआ और रस निकाला हुआ)","1 1/2 बड़े चम्मच जैतून का तेल","1 छोटा चम्मच शहद"],
["एक छोटे सॉसपैन में ब्रॉथ उबालें। क्विनोआ डालकर ढक दें, आँच धीमी कर दें। 15 मिनट तक या ब्रॉथ सूखने तक पकाएँ। क्विनोआ को ठंडा करने के लिए बड़ी बेकिंग शीट पैन पर पतली परत में फैला दें।","जब क्विनोआ कमरे के तापमान पर ठंडा हो जाए, तो अरुगुला को एक बड़ी परोसने वाली थाली में सजाएँ। ऊपर से क्विनोआ, तरबूज़, एवोकाडो, कद्दू के बीज, पुदीना और फ़ेटा डालें।","एक छोटे कटोरे में नीबू का छिलका और रस, तेल और शहद मिलाएँ। मिलाने के लिए फेंटें और ड्रेसिंग को सलाद पर डालें। चाहें तो नमक और काली मिर्च डालें।"]))
r.append(R(6910935,"लो कार्ब सुशी बाउल","यह लो-कार्ब सुशी बाउल टेकआउट का ताज़ा रूप है, जिसमें पारंपरिक चावल की जगह मसालेदार फूलगोभी इस्तेमाल की गई है ताकि स्वाद खोए बिना कार्बोहाइड्रेट कम रहे। झींगा कम वसा वाला प्रोटीन देता है, जबकि एवोकाडो और सब्ज़ियाँ संतोषजनक बनावट और सेहतमंद वसा लाती हैं। यह मधुमेह के अनुकूल विकल्प है जो स्वाद से समझौता किए बिना रक्त शर्करा (ब्लड शुगर) के स्तर में सहायता करता है।","4","3 औंस फूलगोभी राइस + 2 औंस झींगा + 1 कप सब्ज़ियाँ + 1 बड़ा चम्मच मेयो",
["12 औंस फ्रोज़न फूलगोभी राइस","1 बड़ा चम्मच राइस विनेगर","1/2 छोटा चम्मच तिल का तेल","1/8 छोटा चम्मच नमक","1/4 कप लाइट मेयोनेज़","1 बड़ा चम्मच श्रीराचा","1 छोटा चम्मच नीबू का रस","8 औंस झींगा (पका हुआ, कटा हुआ)","1 मध्यम एवोकाडो (कटा हुआ)","1 मध्यम खीरा (जूलियन कटा हुआ)","1/4 कप मूली (पतली कटी हुई)","2 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ)","1 बड़ा चम्मच तिल"],
["फ्रोज़न फूलगोभी राइस को पैकेट के निर्देशों के अनुसार पकाएँ। एक कटोरे में निकालें और सिरका, तिल का तेल और नमक मिलाएँ। इसे कमरे के तापमान तक ठंडा होने दें।","एक छोटे कटोरे में मेयोनेज़, श्रीराचा और नीबू का रस फेंटकर मिलाएँ। एक तरफ़ रख दें।","तैयार करने के लिए, फूलगोभी राइस को 4 कटोरों में बाँटें। हर कटोरे के ऊपर कटा हुआ झींगा, एवोकाडो, खीरा, मूली और हरा प्याज़ रखें।","हर कटोरे पर तीखी मेयो डालें और ऊपर से तिल छिड़कें।"]))
r.append(R(6912355,"ग्रीक कॉटेज चीज़ बाउल","यह सरल ग्रीक कॉटेज चीज़ बाउल मलाईदार, प्रोटीन से भरपूर कॉटेज चीज़ को टमाटर, खीरे और ज़ैतून के कुरकुरे, ज़ायकेदार सलाद के साथ मिलाता है। यह ताज़गी भरा, बिना पकाए बनने वाला भोजन है जो भरपूर फ़ाइबर और सेहतमंद वसा देता है। अपनी कम कार्बोहाइड्रेट मात्रा और संतुलित पोषक तत्वों के साथ, यह ख़ासकर मधुमेह को नियंत्रित करने वालों के लिए उपयुक्त है। यह कम कार्बोहाइड्रेट, कम वसा वाली और शाकाहारी रेसिपी है।","4","1/2 कप कॉटेज चीज़, 1 कप सब्ज़ियाँ",
["1 कप चेरी टमाटर (आधे कटे हुए)","1 छोटा इंग्लिश खीरा (कटा हुआ)","8 साबुत कलामाता ज़ैतून (कटे हुए)","1 बड़ा चम्मच नीबू का रस (ताज़ा)","1 बड़ा चम्मच रेड वाइन सिरका","1 छोटा चम्मच जैतून का तेल","1/2 छोटा चम्मच सूखा अजवायन","1/4 छोटा चम्मच काली मिर्च","2 कप कॉटेज चीज़ (कम वसा वाला)","2 बड़े चम्मच ताज़ा अजमोदा (कटा हुआ)"],
["एक मध्यम कटोरे में चेरी टमाटर, खीरा, ज़ैतून, नीबू का रस, रेड वाइन सिरका, जैतून का तेल, अजवायन और काली मिर्च को मिलाएँ।","कॉटेज चीज़ को 4 कटोरों में बराबर बाँट दें। हर सर्विंग पर ग्रीक सलाद का मिश्रण चम्मच से डालें। ऊपर से ताज़ा अजमोदा डालें।"]))
r.append(R(6912677,"बच्चों की पसंद के मीटबॉल्स","यह मधुमेह के अनुकूल मीटबॉल रेसिपी है जिसे आपका परिवार पसंद करेगा। यह अपने और अपने बच्चों के लिए चुपके से कुछ अतिरिक्त सब्ज़ियाँ खिलाने का बढ़िया तरीका है।","11","2 मीटबॉल्स",
["1/2 कप केचप","3 बड़े चम्मच बालसमिक सिरका","1 पाउंड कीमा टर्की (93% कम वसा)","1/2 मध्यम ज़ुकीनी (कसी हुई)","1 मध्यम गाजर (कसी हुई)","1/2 मध्यम प्याज़ (कसा हुआ)","1 फाँक लहसुन (बारीक कटा हुआ)","2 छोटे चम्मच चिली पाउडर","1/4 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक (वैकल्पिक)","1 बड़ा अंडा (हल्का फेंटा हुआ)","1/2 कप पुराने ज़माने के रोल्ड ओट्स","3 बड़े चम्मच पारमेसन चीज़ (ताज़ा कसा हुआ)"],
["ओवन को 350 डिग्री F पर पहले से गरम करें।","सॉस के लिए एक छोटे कटोरे में केचप और सिरके को फेंटकर मिलाएँ।","एक मध्यम कटोरे में मीटबॉल्स के लिए बाकी सामग्री मिलाएँ। इसे 1 इंच की गेंदों का आकार दें।","मीटबॉल्स को बेकिंग शीट पर रखें और ऊपर से समान रूप से सॉस डालें (प्रति मीटबॉल 1 1/2 छोटा चम्मच)।","45 मिनट तक या पकने तक बेक करें।"]))
r.append(R(6913065,"चिकन टिक्का कबाब","ये चिकन टिक्का कबाब बहुत ज़्यादा कैलोरी या कार्बोहाइड्रेट के बिना बिल्कुल सही मसालों वाले भारतीय भोजन का आनंद लेने का मधुमेह के अनुकूल तरीका हैं।","4","2 सींखें + 1/4 कप त्ज़ात्ज़िकी सॉस",
["3 फाँक लहसुन (कसा हुआ)","1/4 कप सादा वसा रहित ग्रीक दही","2 बड़े चम्मच नीबू का रस","2 छोटे चम्मच नीबू का छिलका (कसा हुआ)","2 छोटे चम्मच पेपरिका","2 छोटे चम्मच पिसा जीरा","2 छोटे चम्मच गरम मसाला","1 छोटा चम्मच हल्दी","1 छोटा चम्मच लाल मिर्च पाउडर","1/2 छोटा चम्मच कोशर नमक","1 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (1 इंच के टुकड़ों में कटे हुए)","1 बड़ी लाल शिमला मिर्च (1 इंच के टुकड़ों में कटी हुई)","1 छोटा लाल प्याज़ (1 इंच के टुकड़ों में कटा हुआ)","8 साबुत बाँस की सींखें (20 मिनट पानी में भिगोई हुई)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 कप त्ज़ात्ज़िकी सॉस (परोसने के लिए)"],
["एक बड़े कटोरे में लहसुन, दही, नीबू का छिलका और रस, मसाले और कोशर नमक को मिलने तक चलाएँ।","कटोरे में चिकन डालें और सभी टुकड़ों पर मैरिनेड समान रूप से लगने तक चलाएँ। ढक दें और 20 मिनट मैरिनेट होने दें (या 24 घंटे तक फ्रिज में रखें)।","मैरिनेड फेंक दें और चिकन को शिमला मिर्च और प्याज़ के साथ बारी-बारी से सींखों में पिरोएँ।","ग्रिल, ग्रिल पैन या तवे पर हल्का सा चिकनाई लगाएँ और तेज़ आँच पर रखें। गरम होने पर सींखों को ग्रिल पर रखें, समान रूप से पकाने के लिए घुमाते हुए, चिकन की मोटाई के अनुसार 12–15 मिनट तक पकाएँ।","कबाब को परोसने से पहले ढककर 5 मिनट रहने दें और त्ज़ात्ज़िकी सॉस के साथ परोसें।"]))
r.append(R(6913457,"क्रॉक पॉट मू शू चिकन","यह बेहद आसान क्रॉक पॉट रेसिपी है जो आपके बाहर रहने के दौरान पकती है और रात के खाने के समय तैयार मिलती है!","4","1 लेट्यूस कप",
["12 औंस ब्रोकली स्लॉ","3 गाजर (कसी हुई)","1 पाउंड बिना हड्डी और बिना त्वचा वाले चिकन ब्रेस्ट (पतले कटे हुए)","3 बड़े चम्मच हॉइसिन सॉस","1/4 कप पानी","3 फाँक लहसुन (बारीक कटा हुआ)","1 छोटा चम्मच कम सोडियम वाला सोया सॉस","1 बड़ा चम्मच कॉर्नस्टार्च","4 बिब या बॉस्टन लेट्यूस के पत्ते"],
["क्रॉकपॉट की तली में स्लॉ मिक्स और गाजर की परत लगाएँ। ऊपर चिकन रखें।","एक छोटे कटोरे में हॉइसिन सॉस, पानी, लहसुन, सोया सॉस और कॉर्नस्टार्च मिलाएँ। चिकन के मिश्रण पर डालें और क्रॉकपॉट को 4-6 घंटे के लिए हाई पर सेट करें।","हर लेट्यूस के पत्ते में 1 1/2 कप मिश्रण परोसें।"]))
r.append(R(6914294,"स्लो कुकर में गाजर और शलजम के साथ ब्रेज़्ड बीफ़","कोमल और रसदार, गाजर और शलजम के साथ यह स्लो कुकर ब्रेज़्ड बीफ़ जो भी खाएगा उसे पसंद आएगा। अपने अगले रविवार के पारिवारिक रात के खाने में इसे परोसकर देखें!","8","1 कप",
["2 बड़े चम्मच जैतून का तेल","1 1/2 पाउंड बीफ़ रोस्ट, बॉटम राउंड, कम वसा वाला, ⅛” ट्रिम, बिना हड्डी का (वसा हटाया हुआ)","1 बड़ा पीला प्याज़ (कटा हुआ)","3 फाँक लहसुन (बारीक कटा हुआ)","1/2 कप पानी","3 बड़े चम्मच टमाटर का पेस्ट","5 बड़ी गाजर (1 इंच के टुकड़ों में कटी हुई)","4 मध्यम शलजम (छिले और कटे हुए)","2 1/2 छोटे चम्मच सूखा थाइम","2 तेज पत्ते","1/2 छोटा चम्मच कोशर नमक","1 छोटा चम्मच काली मिर्च","2 (8 औंस) डिब्बे टमाटर सॉस (कम सोडियम वाला)","14 1/2 औंस कम सोडियम वाला बीफ़ ब्रॉथ"],
["एक बड़ी कड़ाही में मध्यम-तेज़ आँच पर 1 बड़ा चम्मच जैतून का तेल गरम करें। बीफ़ के टुकड़ों को सभी तरफ़ से भूरा करें। भूरे बीफ़ को स्लो कुकर में डालें।","उसी कड़ाही में, ज़रूरत हो तो बचा हुआ 1 बड़ा चम्मच तेल डालें। प्याज़ और लहसुन को नरम होने तक भूनें।","कड़ाही में पानी डालकर तली में चिपके भूरे अंश को खुरचकर निकालें। टमाटर का पेस्ट डालें और मिलाने के लिए चलाएँ।","प्याज़ और टमाटर का मिश्रण स्लो कुकर में डालें।","स्लो कुकर में गाजर, शलजम, सूखा थाइम, तेज पत्ते, नमक और काली मिर्च डालें।","स्लो कुकर में सामग्री पर कम सोडियम वाली टमाटर सॉस और बीफ़ ब्रॉथ डालें।","ढककर धीमी (लो) सेटिंग पर 6–8 घंटे या बीफ़ के नरम होने तक पकाएँ।","परोसने से पहले तेज पत्ते निकाल दें और ज़रूरत हो तो मसाले ठीक करें।"]))
